// Find latest file matching BC_TÀI_CHÍNH pattern
const files = $input.all().map(i => i.json);
const candidates = files.filter(f => {
  const n = (f.name || '').toUpperCase();
  return n.includes('BC') && (n.includes('TÀI') || n.includes('TAI') || n.includes('T_I'));
});
if (candidates.length === 0) {
  throw new Error('Không tìm thấy file BC_TÀI_CHÍNH trong Drive');
}
candidates.sort((a, b) => new Date(b.modifiedTime) - new Date(a.modifiedTime));
return [{ json: { fileId: candidates[0].id, fileName: candidates[0].name, modifiedTime: candidates[0].modifiedTime } }];

// Parse XLSX binary → extract daily records per Notion target DB
// Requires NODE_FUNCTION_ALLOW_EXTERNAL=xlsx env var on n8n container
const XLSX = require('xlsx');

const bin = $input.first().binary?.data;
if (!bin) throw new Error('Không có binary data từ Drive Download');

const buf = Buffer.from(bin.data, 'base64');
const wb = XLSX.read(buf, { type: 'buffer', cellDates: false });

// Sheet name pattern: '15' = ngày 1/5, '215' = ngày 21/5
// Format: <DD><M> where DD = day, M = month digit (last char)
function parseSheetDate(sheetName) {
  const s = (sheetName || '').trim();
  // BC TỔNG is master, skip
  if (s.toUpperCase().includes('TỔNG') || s.toUpperCase().includes('TONG')) return null;
  const m = s.match(/^(\d{1,2})(\d)$/);
  if (!m) return null;
  const day = parseInt(m[1], 10);
  const month = parseInt(m[2], 10);
  const year = 2026; // TODO: derive from file name
  if (day < 1 || day > 31 || month < 1 || month > 12) return null;
  return { day, month, year, iso: `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}` };
}

function num(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return v;
  const s = String(v).replace(/[^0-9.-]/g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
}

function getCell(sheet, cellRef) {
  const c = sheet[cellRef];
  return c ? c.v : null;
}

function hashRow(...parts) {
  // Simple deterministic hash for idempotency
  const str = parts.map(p => String(p ?? '')).join('|');
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

// Map ghi chú text → Hạng mục select
function mapExpenseCategory(note) {
  const n = String(note || '').toLowerCase();
  if (n.includes('lương') || n.includes('luong')) return 'Lương NV';
  if (n.includes('thuê') || n.includes('thue nha')) return 'Thuê nhà';
  if (n.includes('điện') || n.includes('nước') || n.includes('mạng') || n.includes('rác')) return 'Điện nước';
  if (n.includes('vật tư') || n.includes('vat tu')) return 'Vật tư';
  if (n.includes('bảo hiểm') || n.includes('bao hiem')) return 'Bảo hiểm';
  if (n.includes('đồ cúng') || n.includes('do cung')) return 'Đồ cúng';
  if (n.includes('chuyển') || n.includes('rút') || n.includes('chuyen') || n.includes('rut')) return 'Chuyển-Rút';
  if (n.includes('hoàn') || n.includes('hoan')) return 'Hoàn KH';
  return 'Khác';
}

// Map mã GD code → enum
function mapMaGD(code, isCash) {
  const c = String(code || '').toUpperCase().trim();
  // Income codes (cash IN to bank or cash)
  if (c.startsWith('TTHD')) return 'TTHD';
  if (c.startsWith('TTM') && !c.includes('CTD')) return 'TTM';
  if (c.startsWith('TNH')) return 'TNH';
  if (c.startsWith('TT') && !c.startsWith('TTM') && !c.startsWith('TTHD')) return 'TT';
  // Expense codes
  if (c.startsWith('CNH')) return 'CNH';
  if (c.startsWith('CTM')) return 'CTM';
  if (c.startsWith('PCPN') || c.startsWith('PC')) return 'PCPN';
  if (c.startsWith('CTD')) return 'CTD_TTM';
  return null;
}

const cashRecords = [];
const leadRecords = [];
const expenseRecords = [];
const revenueRecords = [];

for (const sheetName of wb.SheetNames) {
  const d = parseSheetDate(sheetName);
  if (!d) continue;
  const ws = wb.Sheets[sheetName];
  if (!ws) continue;

  // ===== Cash Position Daily =====
  // H1 = số dư TK NH cuối ngày, M1 = tiền mặt cuối ngày
  // B3 = tổng tiền vào ngày (recognized to TK)
  // B17 = lưu két riêng, B22 = két cuối ngày
  const tkNHCuoi = num(getCell(ws, 'H1'));
  const tkTMCuoi = num(getCell(ws, 'M1'));
  const tongVao = num(getCell(ws, 'B3'));
  const ketCuoi = num(getCell(ws, 'B22'));
  const ketRieng = num(getCell(ws, 'B17'));
  // Tổng tiền ra = sum chi NH (H14-H26) + chi TM (M14-M26)
  let tongRa = 0;
  for (let r = 14; r <= 26; r++) {
    tongRa += num(getCell(ws, `H${r}`));
    tongRa += num(getCell(ws, `M${r}`));
  }
  cashRecords.push({
    ngayText: `${String(d.day).padStart(2,'0')}/${String(d.month).padStart(2,'0')}/${d.year}`,
    ngayISO: d.iso,
    tkPKDau: 0, // TODO: lấy từ ngày trước hoặc cell khác
    tkPKCuoi: tkNHCuoi + tkTMCuoi - ketRieng, // approx — gộp NH+TM trừ két riêng
    tkCTYDau: 0,
    tkCTYCuoi: ketRieng, // approx — két riêng coi như TK CTY
    tongVao: tongVao,
    tongRa: tongRa,
    sheetName: sheetName.trim()
  });

  // ===== Lead Source Daily =====
  // Row 29: I=FB, J=YT, K=Google, L=KH cũ, M=Khác
  const fb = num(getCell(ws, 'I29'));
  const yt = num(getCell(ws, 'J29'));
  const gg = num(getCell(ws, 'K29'));
  const cu = num(getCell(ws, 'L29'));
  const kh = num(getCell(ws, 'M29'));
  if (fb + yt + gg + cu + kh > 0) {
    leadRecords.push({
      ngayText: `${String(d.day).padStart(2,'0')}/${String(d.month).padStart(2,'0')}/${d.year}`,
      ngayISO: d.iso,
      facebook: fb, youtube: yt, google: gg, khCu: cu, khac: kh
    });
  }

  // ===== Expenses (granular) =====
  // NH expenses: rows 14-26, col H=số tiền, I=mã GD, J=vấn đề chi
  for (let r = 14; r <= 26; r++) {
    const amt = num(getCell(ws, `H${r}`));
    if (amt <= 0) continue;
    const code = getCell(ws, `I${r}`);
    const note = getCell(ws, `J${r}`);
    const cat = mapExpenseCategory(note);
    const maGD = mapMaGD(code, false);
    expenseRecords.push({
      mota: `${cat} ${d.iso} #${r} (NH)`,
      ngayISO: d.iso,
      hangMuc: cat,
      soTien: amt,
      maGD: maGD,
      phuongThuc: 'Chuyển khoản',
      taiKhoan: 'TK Phòng Khám',
      ghiChu: String(note || '').trim(),
      hash: hashRow(d.iso, 'NH', r, amt, code, note)
    });
  }
  // Cash expenses: rows 14-26, col M=số tiền, N=mã GD, O=vấn đề chi, P=note
  for (let r = 14; r <= 26; r++) {
    const amt = num(getCell(ws, `M${r}`));
    if (amt <= 0) continue;
    const code = getCell(ws, `N${r}`);
    const note = getCell(ws, `O${r}`);
    const note2 = getCell(ws, `P${r}`);
    const cat = mapExpenseCategory(note);
    const maGD = mapMaGD(code, true);
    expenseRecords.push({
      mota: `${cat} ${d.iso} #${r} (TM)`,
      ngayISO: d.iso,
      hangMuc: cat,
      soTien: amt,
      maGD: maGD,
      phuongThuc: 'Tiền mặt',
      taiKhoan: 'TK Phòng Khám',
      ghiChu: [note, note2].filter(Boolean).map(s => String(s).trim()).join(' | '),
      hash: hashRow(d.iso, 'TM', r, amt, code, note)
    });
  }

  // ===== Revenue summary (Đào tạo + Dịch vụ) =====
  const doanhThuDaoTao = num(getCell(ws, 'C5'));
  const doanhThuDichVu = num(getCell(ws, 'C6'));
  if (doanhThuDaoTao > 0) {
    revenueRecords.push({
      mota: `Khóa học ${d.iso}`,
      ngayISO: d.iso,
      sale: 'Chung', loai: 'Khóa học',
      soTien: doanhThuDaoTao,
      maGD: null, phuongThuc: null, taiKhoan: null,
      hash: hashRow(d.iso, 'REV', 'DT', doanhThuDaoTao)
    });
  }
  if (doanhThuDichVu > 0) {
    revenueRecords.push({
      mota: `Dịch vụ & mỹ phẩm ${d.iso}`,
      ngayISO: d.iso,
      sale: 'Chung', loai: 'Dịch vụ',
      soTien: doanhThuDichVu,
      maGD: null, phuongThuc: null, taiKhoan: null,
      hash: hashRow(d.iso, 'REV', 'DV', doanhThuDichVu)
    });
  }
}

return [{
  json: {
    summary: {
      cashCount: cashRecords.length,
      leadCount: leadRecords.length,
      expenseCount: expenseRecords.length,
      revenueCount: revenueRecords.length
    },
    cashRecords, leadRecords, expenseRecords, revenueRecords
  }
}];

// Split records into separate items for parallel processing per DB
const d = $input.first().json;
const out = [];
for (const r of d.cashRecords) out.push({ json: { kind: 'cash', ...r } });
for (const r of d.leadRecords) out.push({ json: { kind: 'lead', ...r } });
for (const r of d.expenseRecords) out.push({ json: { kind: 'expense', ...r } });
for (const r of d.revenueRecords) out.push({ json: { kind: 'revenue', ...r } });
return out;

